// Ordinary page navigation keeps forms usable without a JavaScript framework.
document.addEventListener("submit", (event) => {
  const message = event.target.dataset.confirm;
  if (message && !window.confirm(message)) event.preventDefault();
});

document.addEventListener("change", (event) => {
  const form = event.target.closest("form[data-auto-submit]");
  if (form) form.requestSubmit();
});

document.querySelectorAll("[data-question-form]").forEach((form) => {
  const rows = form.querySelector("[data-option-rows]");
  const template = form.querySelector("[data-option-template]");
  form.querySelector("[data-add-option]").addEventListener("click", () => {
    const index = rows.querySelectorAll("[data-option-row]").length;
    const html = template.innerHTML.replaceAll("ROW_INDEX", index).replaceAll("ROW_NUMBER", index + 1);
    rows.insertAdjacentHTML("beforeend", html);
    rows.lastElementChild.querySelector('input[type="text"]').focus();
  });
});

